import datetime
import json
import os
import urllib.parse
import urllib.request


def fetch_json(url):
    request = urllib.request.Request(
        url,
        headers={"User-Agent": "NotchAny-Weather/1.0"},
    )
    with urllib.request.urlopen(request, timeout=12) as response:
        return json.load(response)


def location_label(location):
    name = location.get("city") or location.get("region") or "IP 位置"
    region = location.get("region") or ""
    country = location.get("country") or ""
    labels = [name]
    if region and name not in region and region not in name:
        labels.append(region)
    if country and all(country not in value and value not in country for value in labels):
        labels.append(country)
    return " · ".join(labels)


def ip_location():
    location = fetch_json("https://ipwho.is/?lang=zh-CN")
    if not location.get("success"):
        raise ValueError(location.get("message") or "IP 定位失败")
    return (
        float(location["latitude"]),
        float(location["longitude"]),
        location_label(location),
    )


def forecast_days(latitude, longitude, temperature_unit):
    forecast_query = urllib.parse.urlencode(
        {
            "latitude": latitude,
            "longitude": longitude,
            "daily": (
                "weather_code,temperature_2m_max,temperature_2m_min,"
                "precipitation_probability_max"
            ),
            "temperature_unit": temperature_unit,
            "timezone": "auto",
            "forecast_days": 7,
        }
    )
    forecast = fetch_json("https://api.open-meteo.com/v1/forecast?" + forecast_query)
    daily = forecast.get("daily") or {}
    dates = daily.get("time") or []
    codes = daily.get("weather_code") or []
    highs = daily.get("temperature_2m_max") or []
    lows = daily.get("temperature_2m_min") or []
    rain = daily.get("precipitation_probability_max") or []
    weekdays = ["一", "二", "三", "四", "五", "六", "日"]

    days = []
    for index, iso_date in enumerate(dates[:7]):
        date_value = datetime.date.fromisoformat(iso_date)
        days.append(
            {
                "date": f"{date_value.month}/{date_value.day}",
                "weekday": "今天" if index == 0 else "周" + weekdays[date_value.weekday()],
                "code": int(codes[index]),
                "high": round(float(highs[index])),
                "low": round(float(lows[index])),
                "rain": int(rain[index] or 0),
            }
        )
    if len(days) != 7:
        raise ValueError("天气服务返回的数据不完整")
    return days


unit_choice = (os.environ.get("NOTCH_PARAM_UNIT") or "c").lower()
temperature_unit = "fahrenheit" if unit_choice == "f" else "celsius"
unit_symbol = "°F" if unit_choice == "f" else "°"

try:
    latitude, longitude, location = ip_location()
    state = {
        "city": location,
        "location_mode": "IP 定位",
        "unit": unit_symbol,
        "updated": datetime.datetime.now().strftime("%H:%M"),
        "days": forecast_days(latitude, longitude, temperature_unit),
        "sources": {
            "location": "ipwho.is",
            "weather": "Open-Meteo",
        },
    }
    notch_result(summary="天气已更新", widget=state)
except Exception as error:
    state = {
        "city": "IP 定位",
        "location_mode": "IP 定位",
        "error": "天气数据获取失败",
        "detail": str(error)[:120],
        "days": [],
        "sources": {
            "location": "ipwho.is",
            "weather": "Open-Meteo",
        },
    }
    notch_result(summary="天气获取失败", widget=state)

