:root {
  color-scheme: dark;
  font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", sans-serif;
  container-type: size;
}

* { box-sizing: border-box; }

html, body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: transparent;
  -webkit-user-select: none;
  user-select: none;
}

.weather {
  position: relative;
  width: 100%;
  height: 100%;
  padding: 8px 9px 9px;
  border-radius: 13px;
  background: rgba(255, 255, 255, .09);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .08);
  color: rgba(255, 255, 255, .94);
  display: grid;
  grid-template-rows: 22px minmax(0, 1fr);
  gap: 5px;
}

.topbar {
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.location {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 6px;
}

.location-mark {
  width: 6px;
  height: 6px;
  flex: 0 0 auto;
  border-radius: 50%;
  background: #71c8ff;
  box-shadow: 0 0 0 3px rgba(113, 200, 255, .12);
}

#city {
  max-width: 170px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 11px;
  font-weight: 650;
}

.updated {
  font-size: 9px;
  color: rgba(255, 255, 255, .42);
  white-space: nowrap;
}

.toolbar {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 1px;
}

.source-info,
.refresh {
  width: 22px;
  height: 22px;
  flex: 0 0 auto;
  padding: 0;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: rgba(255, 255, 255, .58);
  cursor: pointer;
}

.source-info {
  position: relative;
  font: 13px/22px -apple-system, BlinkMacSystemFont, sans-serif;
}

.source-info::after {
  content: attr(data-tooltip);
  position: absolute;
  z-index: 5;
  top: 25px;
  right: 0;
  width: 150px;
  padding: 7px 8px;
  border-radius: 7px;
  background: rgb(35, 35, 38);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .10), 0 5px 14px rgba(0, 0, 0, .35);
  color: rgba(255, 255, 255, .86);
  font: 9px/1.45 -apple-system, BlinkMacSystemFont, "PingFang SC", sans-serif;
  text-align: left;
  white-space: pre-line;
  pointer-events: none;
  opacity: 0;
  transform: translateY(-2px);
}

.source-info:hover::after,
.source-info:focus::after,
.source-info.show-source::after {
  opacity: 1;
  transform: translateY(0);
}

.source-info:hover,
.source-info:focus,
.source-info.show-source,
.refresh:hover { background: rgba(255, 255, 255, .10); color: #fff; }

.refresh {
  font: 15px/22px -apple-system, BlinkMacSystemFont, sans-serif;
}

.refresh:active { background: rgba(255, 255, 255, .17); }
.refresh:disabled { cursor: default; opacity: .45; }
.refresh.busy { animation: spin .8s linear infinite; }

@keyframes spin { to { transform: rotate(360deg); } }

.forecast {
  min-width: 0;
  min-height: 0;
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  align-items: stretch;
}

.day {
  min-width: 0;
  padding: 3px 5px 2px;
  border-left: 1px solid rgba(255, 255, 255, .07);
  display: grid;
  grid-template-rows: 13px 11px minmax(23px, 1fr) 15px 12px;
  align-items: center;
  justify-items: center;
  overflow: hidden;
}

.day:first-child { border-left: 0; }
.day.today { background: rgba(113, 200, 255, .08); border-radius: 7px; }

.weekday {
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 9.5px;
  font-weight: 650;
  color: rgba(255, 255, 255, .78);
}

.date {
  font-size: 8px;
  color: rgba(255, 255, 255, .36);
}

.condition {
  font-size: 20px;
  line-height: 1;
  filter: saturate(.9);
}

.temps {
  display: flex;
  align-items: baseline;
  gap: 3px;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.high { font-size: 11px; font-weight: 650; }
.low { font-size: 9px; color: rgba(255, 255, 255, .42); }

.rain {
  font-size: 8px;
  color: rgba(113, 200, 255, .78);
  white-space: nowrap;
}

.message {
  min-width: 0;
  min-height: 0;
  border-radius: 8px;
  background: rgba(255, 255, 255, .05);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  text-align: center;
  padding: 10px;
}

.message[hidden] { display: none; }
.message strong { font-size: 11px; font-weight: 650; }
.message span { max-width: 90%; font-size: 9px; color: rgba(255, 255, 255, .45); overflow-wrap: anywhere; }

@container (max-width: 330px) {
  .weather { padding-left: 6px; padding-right: 6px; }
  .day { padding-left: 2px; padding-right: 2px; }
  .condition { font-size: 17px; }
  .rain { font-size: 7px; }
}

@media (prefers-reduced-motion: reduce) {
  .refresh.busy { animation: none; }
}

