(function () {
  "use strict";

  var city = document.getElementById("city");
  var updated = document.getElementById("updated");
  var forecast = document.getElementById("forecast");
  var sourceInfo = document.getElementById("sourceInfo");
  var refreshButton = document.getElementById("refresh");
  var message = document.getElementById("message");
  var messageTitle = document.getElementById("messageTitle");
  var messageDetail = document.getElementById("messageDetail");
  var timer = null;

  function conditionFor(code) {
    if (code === 0) return { icon: "☀️", label: "晴" };
    if (code === 1 || code === 2) return { icon: "🌤️", label: "多云间晴" };
    if (code === 3) return { icon: "☁️", label: "阴" };
    if (code === 45 || code === 48) return { icon: "🌫️", label: "雾" };
    if (code >= 51 && code <= 57) return { icon: "🌦️", label: "毛毛雨" };
    if (code >= 61 && code <= 67) return { icon: "🌧️", label: "雨" };
    if (code >= 71 && code <= 77) return { icon: "🌨️", label: "雪" };
    if (code >= 80 && code <= 82) return { icon: "🌦️", label: "阵雨" };
    if (code === 85 || code === 86) return { icon: "🌨️", label: "阵雪" };
    if (code >= 95) return { icon: "⛈️", label: "雷雨" };
    return { icon: "☁️", label: "天气" };
  }

  function textNode(className, value) {
    var node = document.createElement("span");
    node.className = className;
    node.textContent = value;
    return node;
  }

  function render(result) {
    var state = result && result.ok ? result.state : null;
    if (!state) return false;

    city.textContent = state.city || "IP 定位";
    var sources = state.sources || {};
    sourceInfo.dataset.tooltip =
      "定位：" + (sources.location || "ipwho.is") + "（公网 IP）\n" +
      "天气：" + (sources.weather || "Open-Meteo");

    if (state.error) {
      forecast.hidden = true;
      message.hidden = false;
      messageTitle.textContent = state.error;
      messageDetail.textContent = state.detail || "请稍后重试";
      updated.textContent = "";
      return true;
    }

    var days = state.days || [];
    if (!days.length) return false;

    var fragment = document.createDocumentFragment();
    days.forEach(function (day, index) {
      var info = conditionFor(day.code);
      var item = document.createElement("article");
      item.className = "day" + (index === 0 ? " today" : "");
      item.title = day.weekday + " · " + info.label + " · " + day.high + state.unit + "/" + day.low + state.unit;
      item.appendChild(textNode("weekday", day.weekday));
      item.appendChild(textNode("date", day.date));
      item.appendChild(textNode("condition", info.icon));

      var temps = document.createElement("div");
      temps.className = "temps";
      temps.appendChild(textNode("high", day.high + state.unit));
      temps.appendChild(textNode("low", day.low + state.unit));
      item.appendChild(temps);
      item.appendChild(textNode("rain", "降雨 " + day.rain + "%"));
      fragment.appendChild(item);
    });

    forecast.replaceChildren(fragment);
    forecast.hidden = false;
    message.hidden = true;
    updated.textContent = "IP 定位 · 更新 " + (state.updated || "刚刚");
    return true;
  }

  function setBusy(busy) {
    refreshButton.disabled = busy;
    refreshButton.classList.toggle("busy", busy);
  }

  function refresh() {
    if (!notchany.visible) return Promise.resolve();
    setBusy(true);
    return notchany.invoke("refresh", null)
      .then(function (result) {
        if (!render(result) && !notchany.state) updated.textContent = "暂无数据";
      })
      .catch(function () {
        updated.textContent = "刷新失败";
      })
      .finally(function () {
        setBusy(false);
      });
  }

  refreshButton.addEventListener("click", refresh);
  sourceInfo.addEventListener("click", function () {
    sourceInfo.classList.toggle("show-source");
  });
  notchany.addEventListener("statechange", function (event) {
    render(event.state || notchany.state);
  });
  notchany.addEventListener("visibilitychange", function () {
    if (timer) {
      clearInterval(timer);
      timer = null;
    }
    if (notchany.visible) {
      refresh();
      timer = setInterval(refresh, 30 * 60 * 1000);
    }
  });

  if (notchany.state) render(notchany.state);
  if (notchany.visible) {
    refresh();
    timer = setInterval(refresh, 30 * 60 * 1000);
  }
})();
